import { z } from 'zod';
import type { Session } from '@/lib/opencode/model';
import type { SessionMetadataRecord } from '@/lib/sessionReviewMetadata';

// Recap + suggested follow-up generated by the server's session-assist
// watcher, stored under session.metadata.openchamber.assist. forMessageID
// names the answer it was written for; freshness is decided by
// getCurrentSessionAssist from session fields alone.
export interface SessionAssistPayload {
  recap: string;
  suggestion: string;
  /** Short replies to the agent's closing question; empty, or 2 to 3 entries. */
  options: string[];
  forMessageID: string;
  generatedAt: number;
}

const OPTION_CHAR_LIMIT = 80;
const MIN_OPTIONS = 2;
const MAX_OPTIONS = 3;
const replyOptionSchema = z.string();

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);

/**
 * The server's option rules, applied again to what the metadata holds: each
 * entry is checked on its own, so one that is not a string, empty, overlong or
 * a case-insensitive repeat drops alone. Fewer than two survivors are no set.
 */
function readReplyOptions(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  const seen = new Set<string>();
  const kept: string[] = [];
  for (const entry of value) {
    const parsed = replyOptionSchema.safeParse(entry);
    if (!parsed.success) continue;
    const text = parsed.data.trim();
    const key = text.toLocaleLowerCase();
    if (!text || text.length > OPTION_CHAR_LIMIT || seen.has(key)) continue;
    seen.add(key);
    kept.push(text);
  }
  return kept.length >= MIN_OPTIONS ? kept.slice(0, MAX_OPTIONS) : [];
}

function getSessionAssist(session: Session | null | undefined): SessionAssistPayload | null {
  const metadata = (session as { metadata?: unknown } | null | undefined)?.metadata;
  if (!isRecord(metadata)) return null;
  const namespace = metadata.openchamber;
  if (!isRecord(namespace)) return null;
  const assist = namespace.assist;
  if (!isRecord(assist)) return null;

  const recap = typeof assist.recap === 'string' ? assist.recap.trim() : '';
  const suggestion = typeof assist.suggestion === 'string' ? assist.suggestion.trim() : '';
  const options = readReplyOptions(assist.options);
  const forMessageID = typeof assist.forMessageID === 'string' ? assist.forMessageID : '';
  if (!forMessageID || (!recap && !suggestion && options.length === 0)) return null;

  return {
    recap,
    // The server never stores both; should a payload carry both, the
    // options win there as well.
    suggestion: options.length > 0 ? '' : suggestion,
    options,
    forMessageID,
    generatedAt: typeof assist.generatedAt === 'number' ? assist.generatedAt : 0,
  };
}

/**
 * The session metadata with the stored suggestion and reply options removed:
 * what the composer's dismiss control writes, so they disappear in every
 * client. The recap and the rest of the metadata stay.
 */
export function withoutAssistSuggestions(metadata: SessionMetadataRecord): SessionMetadataRecord {
  const namespace = isRecord(metadata.openchamber) ? metadata.openchamber : {};
  const assist = isRecord(namespace.assist) ? namespace.assist : {};
  const rest = { ...assist };
  delete rest.suggestion;
  delete rest.options;
  return { ...metadata, openchamber: { ...namespace, assist: rest } };
}

/**
 * The one freshness rule for a stored assist, shared by the sidebar row's
 * recap tooltip (which has only the session record) and the chat (which must
 * agree with it).
 * OpenCode stamps `time.idle` whenever a turn ends, succeeded or not, and the
 * assist is generated after that quiet turn end. A later turn moves `idle`
 * past `generatedAt`, so the payload describes an older turn and is retired.
 * A reverted session shows history that is no longer the active conversation.
 * The server also deletes the assist when a new turn starts; this rule covers
 * payloads written before that, or by another process.
 * Callers still hide it while a turn runs.
 */
export function getCurrentSessionAssist(session: Session | null | undefined): SessionAssistPayload | null {
  const assist = getSessionAssist(session);
  if (!assist || !session) return null;
  if (session.revert?.messageID) return null;
  const idleAt = session.time?.idle ?? 0;
  return assist.generatedAt >= idleAt ? assist : null;
}
